const js = String.raw`
(() => {
  const nav = document.querySelector('.nav-inner');
  document.querySelector('.mobile-toggle')?.addEventListener('click', () => nav?.classList.toggle('menu-open'));
  const amount = document.querySelector('[data-amount]');
  const rate = document.querySelector('[data-rate]');
  const term = document.querySelector('[data-term]');
  const frequency = document.querySelector('[data-frequency]');
  const payment = document.querySelector('[data-payment]');
  const total = document.querySelector('[data-total]');
  const interest = document.querySelector('[data-interest]');
  const next = document.querySelector('[data-next]');
  const chart = document.querySelector('[data-chart]');
  const paid = document.querySelector('[data-paid]');
  const nextStatus = document.querySelector('[data-next-status]');
  const fmt = (n) => 'RD$' + Math.round(n).toLocaleString('es-DO');
  const recalc = () => {
    if (!amount || !rate || !term) return;
    const principal = Number(amount.value), annual = Number(rate.value) / 100, months = Number(term.value);
    const periods = frequency?.value === 'Semanal' ? months * 4 : frequency?.value === 'Quincenal' ? months * 2 : months;
    const periodic = annual / (frequency?.value === 'Mensual' ? 12 : frequency?.value === 'Quincenal' ? 24 : 52);
    const pmt = periodic === 0 ? principal / periods : principal * periodic / (1 - Math.pow(1 + periodic, -periods));
    const grand = pmt * periods;
    const amountOutput = document.querySelector('[data-amount-output]');
    const rateOutput = document.querySelector('[data-rate-output]');
    const termOutput = document.querySelector('[data-term-output]');
    if (amountOutput) amountOutput.textContent = fmt(principal);
    if (rateOutput) rateOutput.textContent = Math.round(Number(rate.value)) + '%';
    if (termOutput) termOutput.textContent = months + ' meses';
    if (payment) payment.textContent = fmt(pmt);
    if (total) total.textContent = fmt(grand);
    if (interest) interest.textContent = fmt(grand - principal);
    if (next) next.textContent = frequency?.value === 'Diaria' ? 'Mañana' : frequency?.value === 'Semanal' ? 'Próximo lunes' : '15 de septiembre';
    if (chart) chart.innerHTML = Array.from({length: 8}, (_, i) => '<i class="bar" style="--h:' + Math.round(35 + (i * 8) + Math.min(25, principal / 10000)) + 'px"></i>').join('');
  };
  [amount, rate, term, frequency].filter(Boolean).forEach((el) => el.addEventListener('input', recalc));
  paid?.addEventListener('click', () => { paid.setAttribute('aria-pressed', 'true'); paid.textContent = 'Cuota registrada'; if (nextStatus) { nextStatus.textContent = 'Al día'; nextStatus.classList.add('is-paid'); } });
  recalc();
  document.querySelectorAll('[data-reveal]').forEach((el) => { const io = new IntersectionObserver((items) => items.forEach((item) => item.isIntersecting && item.target.classList.add('is-visible')), { threshold: .08 }); io.observe(el); });
})();
`;

