function layout({ title, description, url = '/', active = '', content, noindex = false }) {
  const canonical = `${site.replace(/\/$/, '')}${url}`;
  const schema = { '@context': 'https://schema.org', '@graph': [{ '@type': 'Organization', name: 'PréstamoPlus', url: site }, { '@type': 'WebSite', name: 'PréstamoPlus', url: site }, { '@type': 'SoftwareApplication', name: 'PréstamoPlus', applicationCategory: 'BusinessApplication', operatingSystem: 'Web', url: site, description }] };
  return `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#071b2e"><title>${esc(title)}</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="${canonical}"><meta property="og:type" content="website"><meta property="og:site_name" content="PréstamoPlus"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${canonical}"><link rel="icon" href="/marketing-assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/marketing-assets/site.css">${noindex ? '<meta name="robots" content="noindex,nofollow">' : ''}<script type="application/ld+json">${JSON.stringify(schema)}</script></head><body>${header(active)}${content}${footer()}<script src="/marketing-assets/site.js" defer></script></body></html>`;
}

