function resourceIndex() { return `<main><section class="page-hero"><div class="container"><p class="eyebrow" style="color:#6fe1cf">Centro de recursos</p><h1>Ideas para prestar con más orden.</h1><p class="muted">Guías originales sobre cartera, amortización y cobranza para negocios de crédito en República Dominicana.</p></div></section><section class="section"><div class="container"><div class="resource-grid">${resources.map((r) => `<article class="resource-card"><span class="tag">${r.tag}</span><h3>${r.title}</h3><p>${r.intro}</p><a href="/recursos/${r.slug}/">Leer la guía →</a></article>`).join('')}</div></div></section>${cta}</main>`; }
function resourcePage(resource) { return `<main><section class="page-hero"><div class="container article"><div class="breadcrumb"><a href="/recursos/">Recursos</a><span>/</span><span>${resource.tag}</span></div><p class="eyebrow" style="color:#6fe1cf">${resource.tag}</p><h1>${resource.title}</h1><p class="muted lead">${resource.intro}</p></div></section><section class="section"><article class="container article article-body">${resource.sections.map(([h,p]) => `<h2>${h}</h2><p>${p}</p>`).join('')}<div class="callout" style="margin-top:42px"><strong>Cómo lo resuelve PréstamoPlus</strong>La plataforma conecta clientes, préstamos, cuotas, pagos, cobradores y auditoría para que el equipo trabaje sobre la misma información.</div></article></section>${cta}</main>`; }

const contact = `<main><section class="page-hero"><div class="container"><p class="eyebrow" style="color:#6fe1cf">Hablemos</p><h1>Cuéntanos cómo prestas hoy.</h1><p class="muted">Estamos preparando el acceso comercial de PréstamoPlus para negocios de crédito en República Dominicana.</p><div class="hero-actions"><a class="btn btn-primary" href="mailto:hola@prestamoplus.com">Escribir a PréstamoPlus <span aria-hidden="true">↗</span></a><a class="btn btn-ghost" href="/registro">Comenzar la prueba</a></div></div></section><section class="section"><div class="container audience-grid"><article class="audience"><p class="eyebrow">VENTAS</p><h3>¿Evaluando un sistema?</h3><p>Cuéntanos cuántos clientes, préstamos y personas participan en tu operación.</p></article><article class="audience"><p class="eyebrow">SOPORTE</p><h3>¿Ya tienes acceso?</h3><p>Entra al sistema desde el botón de inicio de sesión para consultar tu espacio.</p><a href="/login">Iniciar sesión →</a></article><article class="audience"><p class="eyebrow">UBICACIÓN</p><h3>República Dominicana</h3><p>La primera versión comercial está pensada para el contexto dominicano y su forma de cobrar.</p></article></div></section></main>`;

function writeRoute(route, html) { const dir = route ? path.join(out, route) : out; fs.mkdirSync(dir, { recursive: true }); const withCurrency = route === '' ? html.replace('</main>', `${multiCurrency()}</main>`) : html; const freeHtml = withCurrency.replaceAll('14 días de prueba', 'Sistema gratuito').replaceAll('prueba de 14 días', 'sistema gratuito').replaceAll('Prueba de 14 días', 'Sistema gratuito').replaceAll('14 días para probar', 'Sistema gratuito').replaceAll('14 días. Las condiciones', 'Las condiciones').replaceAll('Comenzar gratis', 'Comenzar').replaceAll('Gratis para comenzar', 'Sistema gratuito').replaceAll('Acceso gratis', 'Sistema gratuito'); fs.writeFileSync(path.join(dir, 'index.html'), freeHtml); }
writeRoute('', layout({ title:'Software de préstamos y cobranza en República Dominicana | PréstamoPlus', description:'PréstamoPlus ayuda a prestamistas, financieras y cooperativas a gestionar clientes, préstamos, pagos, mora y cobradores desde una sola plataforma.', content:home }));
for (const page of pages) writeRoute(page.slug, layout({ title:page.title, description:page.desc, url:`/${page.slug}/`, active:page.active, content:solutionPage(page) }));
writeRoute('precios', layout({ title:'Planes y precios de PréstamoPlus | Software de préstamos', description:'Conoce los planes de PréstamoPlus para organizar tu operación de préstamos y cobranza.', url:'/precios/', active:'precios', content:prices }));
writeRoute('seguridad', layout({ title:'Seguridad y auditoría para tu cartera | PréstamoPlus', description:'Conoce cómo PréstamoPlus separa empresas, limita accesos y conserva trazabilidad operativa.', url:'/seguridad/', content:security }));
writeRoute('calculadora-prestamos', layout({ title:'Calculadora de préstamos y cuotas | PréstamoPlus', description:'Simula cuotas de préstamos por monto, interés, plazo y frecuencia con una herramienta gratuita.', url:'/calculadora-prestamos/', content:calculator }));
writeRoute('recursos', layout({ title:'Recursos sobre préstamos, cartera y cobranza | PréstamoPlus', description:'Guías prácticas para administrar préstamos, tablas de amortización y cobranza en República Dominicana.', url:'/recursos/', content:resourceIndex() }));
for (const resource of resources) writeRoute(`recursos/${resource.slug}`, layout({ title:`${resource.title} | PréstamoPlus`, description:resource.intro, url:`/recursos/${resource.slug}/`, content:resourcePage(resource) }));
writeRoute('contacto', layout({ title:'Contacto | PréstamoPlus', description:'Habla con el equipo de PréstamoPlus sobre tu operación de préstamos.', url:'/contacto/', content:contact }));
writeRoute('404', layout({ title:'Página no encontrada | PréstamoPlus', description:'La página que buscas no existe.', url:'/404/', noindex:true, content:`<main><section class="page-hero"><div class="container"><p class="eyebrow" style="color:#6fe1cf">404</p><h1>Esta página no está en la cartera.</h1><p class="muted">Vuelve al inicio para encontrar lo que buscas.</p><div class="hero-actions"><a class="btn btn-primary" href="/">Ir al inicio</a></div></div></section></main>` }));
fs.mkdirSync(path.join(out, 'marketing-assets'), { recursive:true });
const brandCss = `.brand{flex-shrink:0}.brand-logo{display:block;width:166px!important;height:42px!important;max-width:166px;object-fit:contain;object-position:left center}@media(max-width:620px){.brand-logo{width:142px!important;max-width:142px;height:36px!important}}`;
const currencyCss = `.currency-section{background:#eaf5f8}.currency-grid{display:grid;grid-template-columns:.8fr 1.2fr;gap:54px;align-items:center}.currency-board{background:#071b2e;color:#fff;border-radius:20px;padding:22px;box-shadow:0 18px 42px rgba(7,27,46,.18)}.currency-board-top{display:flex;justify-content:space-between;color:#b8cee1;font-size:.78rem;margin-bottom:18px}.currency-flags{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.currency-chip{display:flex;align-items:center;gap:6px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.1);border-radius:10px;padding:10px 8px;min-width:0}.currency-chip b{font-size:1.2rem}.currency-chip strong{font:600 .72rem 'IBM Plex Mono',monospace}.currency-chip small{display:none}.currency-note{margin-top:16px;color:#9bb4c8;font-size:.72rem;line-height:1.5}@media(max-width:760px){.currency-grid{grid-template-columns:1fr;gap:28px}.currency-flags{grid-template-columns:repeat(4,1fr)}}`;
fs.writeFileSync(path.join(out, 'marketing-assets', 'site.css'), css + brandCss + currencyCss);
fs.writeFileSync(path.join(out, 'marketing-assets', 'site.js'), js);
fs.copyFileSync(path.join(root, 'assets', 'logo-prestamos-plus.svg'), path.join(out, 'marketing-assets', 'logo-prestamos-plus.svg'));
fs.copyFileSync(path.join(root, 'assets', 'icono-prestamos-plus.svg'), path.join(out, 'marketing-assets', 'icono-prestamos-plus.svg'));
fs.copyFileSync(path.join(root, 'assets', 'icono-prestamos-plus.svg'), path.join(out, 'marketing-assets', 'favicon.svg'));

// En local, expone el build React existente para que los CTA de la landing
// también funcionen al servir únicamente marketing/dist con un servidor simple.
const appDist = path.resolve(root, '..', 'dist');
const appIndex = path.join(appDist, 'index.html');
if (fs.existsSync(appIndex)) {
  const appAssets = path.join(appDist, 'assets');
  if (fs.existsSync(appAssets)) fs.cpSync(appAssets, path.join(out, 'assets'), { recursive: true });
  const previewAppIndex = `${fs.readFileSync(appIndex, 'utf8')}<script>(function(){const replace=()=>{const root=document.body;if(!root)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){node.nodeValue=node.nodeValue.replaceAll('La prueba inicia por 14 días sin tarjeta.','El sistema es gratis y no requiere tarjeta.').replaceAll('Registro empresarial · 14 días','Registro empresarial · gratis').replaceAll('14 días sin tarjeta','Acceso gratis sin tarjeta').replaceAll('14 días','gratis');}};replace();new MutationObserver(replace).observe(document.body,{subtree:true,childList:true});})();</script>`;
  for (const route of ['registro', 'login', 'admin', 'portal', 'cobrador', 'plataforma', 'recuperar-contrasena', 'solicitud']) {
    const dir = path.join(out, route);
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(path.join(dir, 'index.html'), previewAppIndex);
  }
}
fs.writeFileSync(path.join(out, 'robots.txt'), `User-agent: *\nAllow: /\nDisallow: /admin\nDisallow: /plataforma\nDisallow: /cobrador\nDisallow: /portal\nDisallow: /login\nDisallow: /registro\nSitemap: ${site.replace(/\/$/, '')}/sitemap.xml\n`);
const urls = ['', ...pages.map((p) => p.slug), 'precios', 'seguridad', 'calculadora-prestamos', 'recursos', ...resources.map((r) => `recursos/${r.slug}`), 'contacto'];
fs.writeFileSync(path.join(out, 'sitemap.xml'), `<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${urls.map((u) => `<url><loc>${site.replace(/\/$/, '')}/${u}${u ? '/' : ''}</loc></url>`).join('')}</urlset>`);
console.log(`Marketing site generated: ${urls.length} pages → ${out}`);
function multiCurrency() { return `<section class="section currency-section"><div class="container currency-grid"><div><p class="eyebrow">El plus de PréstamoPlus</p><h2>Préstamos en multimoneda, sin mezclar saldos.</h2><p class="muted">Administra capital, cuotas y pagos en la moneda de cada operación. Ideal para prestamistas y financieras con cartera en República Dominicana y Latinoamérica.</p><a class="btn btn-dark" href="/gestion-cartera-prestamos/" style="margin-top:24px">Ver gestión multimoneda <span aria-hidden="true">→</span></a></div><div class="currency-board"><div class="currency-board-top"><span>Divisas disponibles</span><span class="mono">ISO 4217</span></div><div class="currency-flags">${[['🇩🇴','DOP','Peso dominicano','do'],['🇺🇸','USD','Dólar estadounidense','us'],['🇪🇺','EUR','Euro','eu'],['🇲🇽','MXN','Peso mexicano','mx'],['🇬🇹','GTQ','Quetzal','gt'],['🇭🇳','HNL','Lempira','hn'],['🇳🇮','NIO','Córdoba','ni'],['🇨🇷','CRC','Colón','cr'],['🇵🇦','PAB','Balboa','pa'],['🇨🇴','COP','Peso colombiano','co'],['🇵🇪','PEN','Sol','pe'],['🇧🇷','BRL','Real','br'],['🇦🇷','ARS','Peso argentino','ar'],['🇨🇱','CLP','Peso chileno','cl'],['🇨🇦','CAD','Dólar canadiense','ca'],['🇬🇧','GBP','Libra esterlina','gb']].map(([flag,code,name,country]) => `<span class="currency-chip"><b><img src="https://flagcdn.com/w40/${country}.png" alt="Bandera ${country}" loading="lazy" width="28" height="20"> </b><strong>${code}</strong><small>${name}</small></span>`).join('')}</div><p class="currency-note">Cada empresa habilita las divisas que necesita desde su configuración.</p></div></div></section>`; }
